    "answer": "第四章 恢复国民经济与各项建设的展开 在有条不紊地进行土地改革和各项民主改革的同时，党和人民政府领导开展了经济、政治、思想文化等多方面的建设。各方面的建设都紧紧围绕着恢复和发展生产这一中心任务。经济方面，全面贯彻实行公私兼顾、劳资两利、城乡互助、内外交流的基本经济方针，促进各种经济成分在国营经济领导下分工合作、各得其所，以发展生产，繁荣经济。政治方面，加强各级政权的民主建设，团结和动员各方面的社会力量参加民主改革和国家建设。思想文化方面，树立马克思列宁主义、毛泽东思想的指导地位，有步骤地对教育文化事业进行改造和建设。在领导建设新中国的实践中，中国共产党开始加强在执政条件下的自身建设。 一、新民主主义经济方针的贯彻 公私兼顾调整城市工商业……",
    "source": "《中国共产党历史·第2卷》",
