    "answer": "第五章 过渡时期总路线和实施发展国民经济的第一个五年计划 1953年，我国开始了以实施发展国民经济第一个五年计划为中心的大规模经济建设。这一年，党正式提出逐步实现国家的社会主义工业化，逐步实现国家对农业、手工业和资本主义工商业的社会主义改造的过渡时期总路线，并把这条总路线作为党和国家一切工作的指针。党还发出号召，要求全国人民认真学习苏联的先进经验来建设我们的国家。由此，中国进入了有计划的经济建设和全面实行社会主义改造的时期。 一、中国共产党在过渡时期的总路线 总路线的酝酿和提出 新民主主义革命胜利后，中国怎样才能从一个落后的、半殖民地半封建的农业国转变为工业国，并使全国各族人民走向社会主义道路呢？对于这个问题，1949年党的七届二中全会已经作了初步规划，指出革命在全国胜利以后，党的一个根本任务是要稳步地促进相互联系的两个转变，一是由农业国向工业国转变，一是由新民主主义社会向社会主义社会转变。至于在什么条件下、从什么时候开始、采取什么方式去实现两个转变，党中央、毛泽东在新中国成立之初提出过一些设想，后来随着客观形势的发展和变化又进行了新的思考。……",
    "source": "《中国共产党历史·第2卷》",
