    "answer": "第六章 全面实行对生产资料私有制的社会主义改造 在进行有计划的经济建设的同时，党领导了生产资料私有制的社会主义改造。在过渡时期，党创造性地开辟了一条适合中国特点的社会主义改造的道路。对个体农业，主要是遵循自愿互利、典型示范和国家帮助的原则，重点发展半社会主义性质的初级农业生产合作社，再发展到社会主义性质的高级农业生产合作社。对个体手工业的改造，也采取了类似的过渡方法。对资本主义工商业，则从委托加工、计划订货、统购包销、委托经销代销等国家资本主义的初级形式，逐步向高级形式的公私合营过渡。在党的社会主义改造方针的正确指导下，1953年至1955年上半年，我国对农业、手工业和资本主义工商业的改造工作，总体上是稳步前进和健康发展的。 一、大力开展农业合作化运动 农业互助合作运动的新发展……",
    "source": "《中国共产党历史·第2卷》",
    "url": ""
