    "q": "第十三章 九个月的初步纠“左”和纠“左”过程中的探索",
    "keywords": [
      "九个月的初步纠“左”和纠“左”过程中的探索"
    ],
    "answer": "第十三章 九个月的初步纠“左”和纠“左”过程中的探索 1958年秋冬之间，党中央开始发现“大跃进”和人民公社化运动中出了不少乱子。毛泽东是“大跃进”和人民公社化运动的倡导者和推动者，也是较早通过初步调查研究觉察到运动中出现问题并努力加以纠正的领导人。从这年11月第一次郑州会议到1959年7月庐山会议前期，中央领导全党作了许多努力，纠正已经觉察到的“左”倾错误。在这个过程中，党提出了一些重要的理论观点和政策主张，对建设社会主义的问题作了一些新的有益探索。 一、对“左”倾错误的初步觉察 毛泽东等人的调查研究 党中央、毛泽东对“左”倾错误的初步觉察，是从发现农村人民公社存在的问题开始的。 北戴河会议之后，“大跃进”和人民公社化运动中出现的一些问题陆续反映到了中央：有的农村发生杀牲口、砍树、藏粮等不正常现象；有的地方遭灾歉收后仍谎报产量、多征购粮食，导致饿死人的事情发生 【118】 ；还有的地方，人民公社的牌子刚刚挂出，就急忙宣布人民公社为“全民所有制”，搞“向共产主义过渡”的试点。河北省徐水县率先成立了全县范围的公社，并称实现了全县“全民所有制”。毛泽东曾派人去徐水了解情况，发现不少问题。……",
    "source": "《中国共产党历史·第2卷》",
    "url": ""
