    "answer": "第十五章 对国民经济和社会政治关系的全面调整 进入60年代，国内经济形势十分严峻。面对继续“大跃进”造成的经济全面紧张，全党和中央决心认真调查研究，纠正错误，调整政策。1960年11月，党中央发出《关于农村人民公社当前政策问题的紧急指示信》；1961年1月，党的八届九中全会正式决定对国民经济实行“调整、巩固、充实、提高”的八字方针。这两件事标志着党的指导方针的重要转变。“大跃进”和向基本社有制的过渡停止了。全党上下与人民群众同甘共苦，克服困难。同时，党继续第一次郑州会议到庐山会议前期和1960年6月中央政治局扩大会议纠“左”的努力，为进一步探索中国自己的建设社会主义道路积累了新的经验。 一、调整方针的提出和初步贯彻 《关于农村人民公社当前政策问题的紧急指示信》的发出……",
