    "answer": "第十七章 国民经济调整任务的完成和“四个现代化”目标的提出 1962年上半年，全党集中全力对国民经济实行调整，国民经济逐渐复苏，各项建设事业有了明显的健康发展势头。党中央从实际情况出发，认为在今后三年内，仍需继续贯彻“调整、巩固、充实、提高”的八字方针。从1962年下半年到1965年，国民经济开始稳步增长，社会呈现欣欣向荣的景象。在这期间，国民经济接近并达到和超过新中国成立以来最高水平。人民物质生活普遍得到改善。基础科学研究和尖端武器的研制取得重大进展。一些重要的技术发明和创造，处在当时国际领先水平。为了克服物质困难，全国人民团结一致，意气风发、勇敢前行，进行了艰苦卓绝的工作。许多奇迹般的业绩在这期间被创造出来。在国际形势复杂变幻、超级大国加大对中国政治、经济、军事的压力面前，中国人民毫不畏惧，坚持正义、坚持和平，出色地应对了挑战。党中央通过1964年底举行的三届全国人大一次会议，向全国人民提出建设“四个现代化”的伟大目标，极大地激发了亿万人民建设社会主义国家的积极性。 一、国民经济调整的继续和完成 继续调整的重大决策及其主要进展……",
    "source": "《中国共产党历史·第2卷》",
    "url": ""
