    "answer": "第二十九章 “文化大革命”的结束和“左”的指导方针的延续 粉碎“四人帮”的胜利，虽然结束了“文化大革命”的内乱，但是，持续十年的“文化大革命”积累下许多严重的政治问题和社会问题，给党和国家造成的严重后果及影响仍然存在。党在粉碎“四人帮”后面临的任务相当艰巨。为重建党组织的正常秩序，恢复党的优良传统和作风；为重建国家生活的正常秩序，使各级政权机关正常运转，使遭到严重破坏的各项事业重新振兴，有许多迫切的工作要做。粉碎“四人帮”后，党中央立即采取措施，稳定局势，摧毁和清查“四人帮”的残余势力，发动对“四人帮”的揭发和批判。党和国家组织机构的整顿，冤假错案的平反，开始部分地进行。工农业生产得到比较快的恢复，教育科学文化工作也开始走向正常。邓小平在1975年通过领导整顿开始的、后因“反击右倾翻案风”被迫中断的对“文化大革命”的拨乱反正，又重新局部地进行。党和人民对国家从困境中奋起充满希望，以极大的热情投入各项工作；同时，对于纠正“文化大革命”中的错误的要求也日益强烈。然而，进行拨乱反正需要有一个过程。由于“两个凡是”错误方针的提出和推行，人民群众的要求未能得到满足，拨乱反正的开展遇到了阻碍。……",
    "source": "《中国共产党历史·第2卷》",
