    "answer": "第三十一章 实现历史的伟大转折 随着真理标准问题讨论和各条战线拨乱反正的开展，在邓小平的推动和其他老一辈革命家的支持下，1978年底召开的中央工作会议和党的十一届三中全会，终于在党和国家面临向何处去的重大历史关头，就关系党和国家前途命运的大政方针作出了正确的政治决断和战略抉择，实现了新中国成立以来我们党历史上具有深远意义的伟大转折。 一、对国际形势的正确判断和外交工作的积极成果 20世纪70年代后期，中国面临的国际形势主要呈现两个特点：一是美国和苏联两个超级大国争夺世界霸权带来的战争危险，不但威胁着广大发展中国家，也威胁到一些资本主义发达国家，这些国家都希望同中国发展关系，以摆脱超级大国的控制，减少战争威胁；二是由于70年代中期世界经济危机的打击和新一轮科学技术革命的兴起，主要资本主义国家的生产设备和资金大量闲置，市场萎缩，普遍面临摆脱经济萧条、调整产业结构、开辟新的市场的需要。很多发展中国家则纷纷利用资本主义国家进行产业结构调整的时机，引进资金和技术，寻求加快经济发展的途径。……",
