    "q": "美国“调解”真相和中国内战前途",
    "keywords": [
      "美国“调解”真相和中国内战前途"
    ],
    "answer": "（一九四六年九月二十九日） 斯蒂尔问：阁下是否认为美国调解中国内战之举已告失败？如美国政策按目前形式继续实行，则结局将如何？ 毛答：我很怀疑美国政府的政策是所谓调解⑴。根据美国大量援助蒋介石使得他能够举行空前大规模内战的事实看来，美国政府的政策是在借所谓调解作掩护，以便从各方面加强蒋介石，并经过蒋介石的屠杀政策，压迫中国民主力量，使中国在实际上变为美国的殖民地。这一政策继续实行下去，必将激起全中国一切爱国人民起来作坚决的反抗。 问：中国内战将延长多久？其结果将如何？ 答：如果美国政府放弃现行援蒋政策，撤退驻华美军，实行莫斯科苏美英三国外长会议的协定⑵，则中国内战必能早日结束。如果不是这样，就有变为长期战争的可能。其结果，一方面，当然是中国人民受痛苦；但是，另一方面，中国人民必将团结起来，保卫自己的生存，决定自己的命运。不管怎样艰难困苦，中国人民的独立、和平、民主的任务是一定要实现的。任何本国和外国的压迫力量，不可能阻止这一任务的实现。",
