    "answer": "《中国革命和中国共产党》，是一九三九年冬季，由毛泽东和其他几个在延安的同志合作写作的一个课本。第一章《中国社会》，是其他几个同志起草，经过毛泽东修改的。第二章《中国革命》，是毛泽东自己写的。第三章，准备写《党的建设》，因为担任写作的同志没有完稿而停止。但是这两章，特别是第二章，在中国共产党和中国人民中仍然起了很大的教育作用。毛泽东在这个小册子的第二章中关于新民主主义的观点，在一九四○年一月他所写的《新民主主义论》中大为发展了。 第一节 中华民族 我们中国是世界上最大国家之一，它的领土和整个欧洲的面积差不多相等。在这个广大的领土之上，有广大的肥田沃地，给我们以衣食之源；有纵横全国的大小山脉，给我们生长了广大的森林，贮藏了丰富的矿产；有很多的江河湖泽，给我们以舟楫和灌溉之利；有很长的海岸线，给我们以交通海外各民族的方便。从很早的古代起，我们中华民族的祖先就劳动、生息、繁殖在这块广大的土地之上。……",
