    "answer": "中国共产党第七届中央委员会第二次全体会议，一九四九年三月五日至十三日举行于河北省平山县西柏坡村。出席的有中央委员三十四人，候补中央委员十九人。这次会议是在中国人民革命全国胜利的前夜召开的，是一次极其重要的会议。毛泽东在这次会议上所作的报告，提出了促进革命迅速取得全国胜利和组织这个胜利的各项方针；说明了在全国胜利的局面下，党的工作重心必须由乡村移到城市，城市工作必须以生产建设为中心；规定了党在全国胜利以后，在政治、经济、外交方面应当采取的基本政策，特别着重地分析了当时中国经济各种成分的状况和党所必须采取的正确政策，指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向。毛泽东估计了中国人民民主革命胜利以后的国内外阶级斗争的新形势，及时地警告资产阶级的“糖衣炮弹”将成为对于无产阶级的主要危险。毛泽东的这个报告，和他在同年六月所写的《论人民民主专政》一文，构成了为中国人民政治协商会议第一届全体会议所通过的、在新中国成立初期曾经起了临时宪法作用的《共同纲领》的政策基础。党的第七届中央委员会第二次全体会议，根据毛泽东的报告，通过了相应的决议。在这次会议以后，中共中央就由河北……",
