    "answer": "这是毛泽东在一九三七年五月二日至十四日在延安召开的中国共产党全国代表会议上的报告。 民族矛盾和国内矛盾的目前发展阶段 （一）由于中日矛盾成为主要的矛盾、国内矛盾降到次要和服从的地位而产生的国际关系和国内阶级关系的变化，形成了目前形势的新的发展阶段。 （二）中国很久以来就是处在两种剧烈的基本的矛盾中——帝国主义和中国之间的矛盾，封建制度和人民大众之间的矛盾。一九二七年以国民党为代表的资产阶级叛变革命，出卖民族利益于帝国主义，造成了工农政权和国民党政权尖锐对立，以及民族和民主革命的任务不能不由中国共产党单独负担的局面。 （三）一九三一年九一八事变⑴特别是一九三五年华北事变⑵以来的形势，使这些矛盾发生了如下的变化：",
