    "answer": "这是毛泽东在陕甘宁边区文教工作者会议上所作的讲演。 我们的一切工作都是为了打倒日本帝国主义。日本帝国主义和希特勒一样，快要灭亡了。但是还须我们继续努力，才能最后地消灭它。我们的工作首先是战争，其次是生产，其次是文化。没有文化的军队是愚蠢的军队，而愚蠢的军队是不能战胜敌人的。……",
