    "q": "原子弹吓不倒中国人民",
    "keywords": [
      "原子弹吓不倒中国人民"
    ],
    "answer": "*这是毛泽东同志在芬兰首任驻中国大使孙士教递交国书的时候谈话的要点。 中国和芬兰是友好的国家。我们的关系，是建立在和平共处五项原则的基础之上的。 中国同芬兰从来没有发生过冲突。在欧洲国家中，在历史上，中国只同英国、法国、德国、沙皇俄国、意大利、奥匈帝国、荷兰等国有过战争，都是这些国家从老远跑来侵略中国的，比如英法联军和包括美国、日本在内的八国联军对中国的进攻。参加侵朝战争的有十六个国家，其中有土耳其、卢森堡等国。这些侵略国家都说他们是爱好和平的，却把朝、中两国说成是侵略国。 今天，世界战争的危险和对中国的威胁主要来自美国的好战分子。他们侵占中国的台湾和台湾海峡，还想发动原子战争。我们有两条：第一，我们不要战争；第二，如果有人来侵略我们，我们就予以坚决回击。我们对共产党员和全国人民就是这样进行教育的。美国的原子讹诈，吓不倒中国人民。我国有六亿人口，有九百六十万平方公里的土地。美国那点原子弹，消灭不了中国人。即使美国的原子弹威力再大，投到中国来，把地球打穿了，把地球炸毁了，对于太阳系说来，还算是一件大事情，但对整个宇宙说来，也算不了什么。……",
    "source": "《毛泽东选集》",
    "url": ""
