    "q": "《共产党人》发刊词",
    "keywords": [
      "《共产党人》发刊词"
    ],
    "answer": "中央很早就计划出版一个党内的刊物，现在算是实现了。为了建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的布尔什维克化的中国共产党，这样一个刊物是必要的。在当前的时机中，这种必要性更加明显。当前时机中的特点，一方面，是抗日民族统一战线中的投降危险、分裂危险和倒退危险日益发展着；又一方面，是我们党已经走出了狭隘的圈子，变成了全国性的大党。而党的任务是动员群众克服投降危险、分裂危险和倒退危险，并准备对付可能的突然事变，使党和革命不在可能的突然事变中，遭受出乎意料的损失。在这种时机，这样一个党内刊物的出版，实在是十分必要的了。 这个党内刊物定名为《共产党人》。它的任务是什么呢？它将写些什么东西呢？它和别的党报有些什么不同呢？ 它的任务就是：帮助建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的布尔什维克化的中国共产党。为了中国革命的胜利，迫切地需要建设这样一个党，建设这样一个党的主观客观条件也已经大体具备，这件伟大的工程也正在进行之中。帮助进行这件伟大的工程，不是一般党报所能胜任的，必须有专门的党报，这就是《共产党人》出版的原因。……",
