    "q": "团结起来，划清敌我界限",
    "keywords": [
      "团结起来",
      "划清敌我界限"
    ],
    "answer": "* 这是毛泽东同志在中国人民政治协商会议第一届全国委员会常务委员会第三十八次会议上讲话的要点。 去年这一年，我们是边打，边谈，边稳。 朝鲜战争的局势，去年七月以后定下来了，但是国内的财政经济状况，能不能稳下来，那时还没有把握。过去只是讲“物价基本稳定，收支接近平衡”，意思是说，物价还不能稳定，收支还没有平衡。收入少，支出多，这是个问题。困此，中共中央在去年九月开了一次会，提出增加生产，厉行节约。十月，我又在政协第一届全国委员会第三次会议上，提出增产节约。在增产节约运动中，揭发出相当严重的贪污、浪费、官僚主义的问题，到十二月开展了“三反”运动，接着又开展了“五反”运动。现在“三反”“五反”运动胜利结束，问题完全清楚了，天下大定。 去年抗美援朝战争的费用，和国内建设的费用大体相等，一半一半。今年不同，战争费用估计只要用去年的一半。现在我们的部队减少了，但是装备加强了。我们过去打了二十几年仗，从来没有空军，只有人家炸我们。现在空军也有了，高射炮、大炮、坦克都有了。抗美援朝战争是个大学校，我们在那里实行大演习，这个演习比办军事学校好。如果明年再打一年，全部陆军都可以轮流去训练一回。……",
    "source": "《毛泽东选集》",
