    "answer": "这是毛泽东为中共中央起草的对党内的指示。 （一）从何白《皓电》（去年十月十九日）开始的第二次反共高潮⑴，至皖南事变和蒋介石一月十七日命令⑵达到了最高峰；而三月六日蒋介石的反共演说和参政会的反共决议⑶，则是此次反共高潮的退兵时的一战。时局可能从此暂时走向某一程度的缓和。处于世界两大帝国主义集团进行着有决定意义的斗争的前夜，依然和日寇对立着的中国英美派大资产阶级，不能不对目前紧张的国共关系，谋取暂时的和轻微的缓和。同时，国民党内部的情况（中央和地方之间，CC系和政学系⑷之间，CC系和复兴系⑸之间，顽固派和中间派之间，皆有矛盾，CC系内部和复兴系内部又各有矛盾），国内的情况（广大人民反对国民党的专横，同情共产党）和我党的政策（继续抗议运动），均不容许国民党在国共间继续过去五个月那样的紧张关系。故目前谋取暂时的轻微的缓和是蒋介石所需要的。……",
