    "answer": "这是毛泽东在延安人民追悼平江惨案死难烈士大会上的演说。 今天是八月一日，我们在这里开追悼大会。为什么要开这样的追悼会呢？因为反动派杀死了革命的同志，杀死了抗日的战士。现在应该杀死什么人？应该杀死汉奸，杀死日本帝国主义者。但是，中国和日本帝国主义者打了两年仗，还没有分胜负。汉奸还是很活跃，杀死的也很少。革命的同志，抗日的战士，却被杀死了。什么人杀死的？军队杀死的。军队为什么杀死了抗日战士？军队是执行命令，有人指使军队去杀的。什么人指使军队去杀？反动派在那里指使⑴。同志们！照理说，什么人要杀抗日战士呢？第一是日本帝国主义者要杀他们，第二是汪精卫⑵等汉奸卖国贼要杀他们。但是现在杀人的地方不是在上海、北平、天津、南京，不是在日寇汉奸占领的地方，而是在平江这个地方，在抗战的后方，被杀死的是新四军平江通讯处的负责同志涂正坤、罗梓铭等。很明显，是那班中国反动派接受了日本帝国主义和汪精卫的命令来杀人的。这些反动派，他们是准备投降的，所以恭恭敬敬地执行了日本人和汪精卫的命令，先把最坚决的抗日分子杀死。这件事非同小可，我们一定要反对，我们一定要抗议！……",
