    "answer": "这是毛泽东为中共中央写的对党内的指示。 （一）秋收已到，各根据地的领导机关必须责成各级党政机关检查减租政策的实行情况。凡未认真实行减租的，必须于今年一律减租。减而不彻底的，必须于今年彻底减租。党委应即根据中央土地政策和当地情况发出指示，并亲手检查几个乡村，发现模范，推动他处。同时，应在报纸上发表关于减租的社论和关于减租的模范经验的报道。减租是农民的群众斗争，党的指示和政府的法令是领导和帮助这个群众斗争，而不是给群众以恩赐。凡不发动群众积极性的恩赐减租，是不正确的，其结果是不巩固的。在减租斗争中应当成立农民团体，或改造农民团体。政府应当站在执行减租法令和调节东佃利益的立场上。现在根据地已经缩小，我党在根据地内细心地认真地彻底地争取群众、和群众同生死共存亡的任务，较之过去六年有更加迫切的意义。今秋如能检查减租政策的实施程度，并实行彻底减租，就能发扬农民群众的积极性，加强明年的对敌斗争，推动明年的生产运动。……",
