    "answer": "蒋介石氏在西安接受张学良杨虎城二将军和西北人民的抗日的要求⑴，首先命令进行内战的军队撤离陕甘两省，这是蒋介石氏转变其十年错误政策的开始。这对于指挥内战、制造分裂、并欲在这次事变中置蒋氏于死地的日本帝国主义和中国讨伐派⑵的阴谋，给了一个打击。日本帝国主义和中国讨伐派的失望，已显而易见。蒋氏此种觉悟的表示，可以看作国民党愿意结束其十年错误政策的一种表示。 蒋介石氏十二月二十六日在洛阳发表了一个声明，即所谓《对张杨的训词》⑶，内容含含糊糊，曲曲折折，实为中国政治文献中一篇有趣的文章。蒋氏果欲从这次事变获得深刻的教训，而为建立国民党的新生命有所努力，结束其传统的对外妥协、对内用兵、对民压迫的错误政策，将国民党引导到和人民愿望不相违背的地位，那末，他就应该有一篇在政治上痛悔已往开辟将来的更好些的文章，以表现其诚意。十二月二十六日的声明，是不能满足中国人民大众的要求的。……",
