    "q": "斯大林是中国人民的朋友",
    "keywords": [
      "斯大林是中国人民的朋友"
    ],
    "answer": "今年十二月二十一日，是斯大林同志的六十岁生日。这个生日，在全世界上，在只要是知道的又是革命的人们的心中，可以料得到，都会引起亲切的热烈的庆祝。 庆祝斯大林，这不是一件应景的事情。庆祝斯大林，这就是说，拥护他，拥护他的事业，拥护社会主义的胜利，拥护他给人类指示的方向，拥护自己的亲切的朋友。因为现在全世界上大多数的人类都是受难者，只有斯大林指示的方向，只有斯大林的援助，才能解脱人类的灾难。 我们中国人民，是处在历史上灾难最深重的时候，是需要人们援助最迫切的时候。《诗经》上说的：“嘤其鸣矣，求其友声。”我们正是处在这种时候。 但是，谁是我们的朋友呢？ 一类所谓朋友，他们自称是中国人民的朋友；中国人中间有些人也不加思索地称他们做朋友。但是这种朋友，只能属于唐朝的李林甫⑴一类。李林甫是唐朝的宰相，是一个有名的被称为“口蜜腹剑”的人。现在这些所谓朋友，正是“口蜜腹剑”的朋友。这些人是谁呢？就是那些口称同情中国的帝国主义者。",
    "source": "《毛泽东选集》",
