    "answer": "国民党反动统治崩溃的速度，比人们预料的要快。现在距离解放军攻克济南只有四个多月，距离攻克沈阳只有三个多月，但是国民党在军事上、政治上、经济上、文化宣传上的一切残余力量，却已经陷于不可挽救的四分五裂、土崩瓦解的状态。国民党统治的总崩溃开始于北线的辽沈战役⑴、平津战役⑵和南线的淮海战役⑶期间，这三个战役使国民党在去年十月初至今年一月底的不足四个月中丧失约一百五十四万多人，包括国民党正规军一百四十四个整师。国民党统治总崩溃是中国人民解放战争和中国人民革命运动伟大胜利的必然结果，但是国民党及其美国主人的“和平”叫嚣，对于促进国民党崩溃一事，也起了相当的作用。国民党反动派从今年一月一日开始搬起的一块名叫“和平攻势”的石头，原想用来打击中国人民的，现在是打在他们自己的脚上了。或者说得正确些，是把国民党自己从头到脚都打烂了。除了傅作义将军协助人民解放军已经和平地解决了北平问题以外，各地希望和平解决的还大有人在。美国人站在一旁发干急，深恨其儿子们不争气。其实，和平攻势这个法宝出产于美国工厂，还在大半年以前就由美国人送给了国民党。司徒雷登⑷本人曾经泄露了这个秘密。他在蒋介石发出所谓元旦文告以后，曾告中央……",
    "source": "《毛泽东选集》",
