    "answer": "（一九四二年五月二日） 同志们！今天邀集大家来开座谈会，目的是要和大家交换意见，研究文艺工作和一般革命工作的关系，求得革命文艺的正确发展，求得革命文艺对其他革命工作的更好的协助，借以打倒我们民族的敌人，完成民族解放的任务。……",
    "source": "《毛泽东选集》",
