    "answer": "*这是毛泽东同志在中共中央召集的省委、市委、自治区党委书记会议上的报告。 在全国农村中，新的社会主义群众运动的高潮就要到来。我们的某些同志却像一个小脚女人，东摇西摆地在那里走路，老是埋怨旁人说:走快了，走快了。过多的评头品足，不适当的埋怨，无穷的忧虑，数不尽的清规和戒律，以为这是指导农村中社会主义群众运动的正确方针。 否，这不是正确的方针，这是错误的方针。……",
