    "q": "反对党内的资产阶级思想",
    "keywords": [
      "反对党内的资产阶级思想"
    ],
    "answer": "*这是毛泽东同志在一九五三年夏季全国财经工作会议上的讲话。 这次会议开得很好，周总理的结论也作得好。 现在我们可以看出，在“三反”“五反”运动之后，党内有两种性质的错误。一种是一般性的错误，如“五多”，大家都可能犯，什么时候都可能犯。“五多”的错误也可以变成“五少”的错误。另一种是原则性的错误，如资本主义倾向。这是资产阶级思想在党内的反映，是违背马克思列宁主义的立场问题。 “三反”“五反”运动，是对党内资产阶级思想的很大打击。但是，当时仅仅给了贪污浪费这方面的资产阶级思想以基本打击，而对在路线问题上反映出来的资产阶级思想并没有解决。这种资产阶级思想，不仅财经工作中有，而且政法、文教和其他工作中也有，中央同志中和地方同志中都有。 对于财经工作中的错误，从去年十二月薄一波同志提出“公私一律平等”的新税制开始，到这次会议，都给了严肃的批评。新税制发展下去，势必离开马克思列宁主义，离开党在过渡时期的总路线，向资本主义发展。",
    "source": "《毛泽东选集》",
