    "answer": "*这是毛泽东为纪念孙中山诞辰九十周年写的文章。 纪念伟大的革命先行者孙中山先生! 纪念他在中国民主革命准备时期，以鲜明的中国革命民主派立场，同中国改良派作了尖锐的斗争。他在这一场斗争中是中国革命民主派的旗帜。 纪念他在辛亥革命时期，领导人民推翻帝制、建立共和国的丰功伟绩。 纪念他在第一次国共合作时期，把旧三民主义发展为新三民主义的丰功伟绩。",
    "source": "《毛泽东选集》",
