    "answer": "*这是毛泽东同志审阅周恩来同志在一九五三年夏季全国财经工作会议上的结论时所作的重要批示。 从中华人民共和国成立，到社会主义改造基本完成，这是一个过渡时期。党在这个过渡时期的总路线和总任务，是要在一个相当长的时期内，基本上实现国家工业化和对农业、手工业、资本主义工商业的社会主义改造。这条总路线， 应是照耀我们各项工作的灯塔， 各项工作离开它，就要犯右倾或“左”倾的错误。 这条总路线的许多方针政策，在一九四九年三月的党的二中全会的决议里就已提出，并已作了原则性的解决。可是许多同志却不愿意遵照二中全会的规定去工作，喜欢在某些问题上另闹一套不符合于二中全会规定的东西，甚至公然违反二中全会的原则。",
