    "answer": "这是毛泽东为延安《解放日报》写的社论。 自从党中央提出精兵简政⑴这个政策以来，许多抗日根据地的党，都依照中央的指示，筹划和进行了这项工作。晋冀鲁豫边区的领导同志，对这项工作抓得很紧，做出了精兵简政的模范例子。但是还有若干根据地的同志们因为认识不够，没有认真地进行。这些地方的同志们还不理解精兵简政同当前形势和党的各项政策的关系，还没有把精兵简政当作一个极其重要的政策看待。关于这件事，《解放日报》曾多次讨论，今愿更有所说明。……",
