    "answer": "这是毛泽东在陕北瓦窑堡党的活动分子会议上所作的报告。毛泽东的这个报告是在一九三五年十二月中共中央政治局瓦窑堡会议之后作的。这一次政治局会议批评了党内那种认为中国民族资产阶级不可能和中国工人农民联合抗日的错误观点，决定了建立抗日民族统一战线的策略，是一次极关重要的会议。毛泽东根据中央决议在这里充分地说明了和民族资产阶级在抗日的条件下重新建立统一战线的可能性和重要性，着重地指出共产党和红军在这个统一战线中的具有决定意义的领导作用，指出了中国革命的长期性，批判了党内在过去长时期内存在着的狭隘的关门主义和对于革命的急性病——这些是党和红军在第二次国内革命战争时期遭受严重挫折的基本原因。同时，毛泽东唤起党内注意一九二七年陈独秀右倾机会主义引导革命归于失败的历史教训，指出了蒋介石必然要破坏革命势力的趋势，这样就保证了后来中国共产党在新环境中能够具有清醒的头脑，在蒋介石的无穷欺骗和很多次的武装袭击中，使革命力量不致遭受损失。一九三五年一月中共中央在贵州遵义举行的政治局扩大会议，建立了以毛泽东为代表的新的中央的领导，改变了过去“左”倾机会主义的领导。但那次会议是在红军长征途中召集的，所以只能够对于当时……",
