    "answer": "这是毛泽东给欧洲共产党和工人党情报局机关刊物《争取持久和平，争取人民民主！》所写的纪念十月革命三十一周年的论文。这篇论文发表在该刊一九四八年第二十一期。 现在，当着全世界觉悟的工人阶级和一切真诚革命的人们对于苏联伟大的十月社会主义革命第三十一个周年举行欢欣鼓舞的纪念的时候，我想起了斯大林在一九一八年，在十月革命第一个周年纪念的时候所写的著名的论文。斯大林在这篇论文中说：“十月革命的伟大的世界意义，主要的是：第一，它扩大了民族问题的范围，把它从欧洲反对民族压迫的斗争的局部问题，变为各被压迫民族、各殖民地及半殖民地从帝国主义之下解放出来的总问题；第二，它给这一解放开辟了广大的可能性和现实的道路，这就大大地促进了西方和东方的被压迫民族的解放事业，把他们吸引到胜利的反帝国主义斗争的巨流中去；第三，它从而在社会主义的西方和被奴役的东方之间架起了一道桥梁，建立了一条从西方无产者经过俄国革命到东方被压迫民族的新的反对世界帝国主义的革命战线。”⑴……",
