    "answer": "各位参议员先生，各位同志：今天边区参议会开幕，是有重大意义的。参议会的目的，只有一个，就是要打倒日本帝国主义，建设新民主主义的中国，也就是革命的三民主义的中国。现在的中国不能有别的目的，只能有这个目的。因为现在我们的主要敌人不是国内的，而是日本和德意法西斯主义。现在苏联红军正在为苏联和全人类的命运奋斗，我们则在反对日本帝国主义。日本帝国主义还在继续侵略，它的目的是要灭亡中国。中国共产党的主张就是要团结全国一切抗日力量打倒日本帝国主义，要和全国一切抗日的党派、阶级、民族合作，只要不是汉奸，都要联合一致，共同奋斗。共产党的这种主张，是始终一致的。中国人民英勇抗战已有四年多，这个抗战是由国共两党的合作和各阶级各党派各民族的合作来支持的。但是还没有胜利；还要继续奋斗，还要使革命的三民主义见之实行，才能胜利。……",
