    "answer": "《中国工人》⑴的出版是必要的。中国工人阶级，二十年来，在自己的政党——中国共产党的领导之下展开了英勇的斗争，成了全国人民中最有觉悟的部分，成了中国革命的领导者。中国工人阶级联合农民和一切革命的人民反对帝国主义和封建主义，为建立新民主主义的中国而斗争，为驱逐日本帝国主义而斗争，这个功劳是非常之大的。但是中国革命尚未成功，还须付出很大的气力，团结自己，团结农民和其他小资产阶级，团结知识分子，团结一切革命的人民。这是极大的政治任务和组织任务。这是中国共产党的责任，这是工人阶级先进分子的责任，这是整个工人阶级的责任。工人阶级和全体人民的最后解放，只能在社会主义实现的时代，中国工人阶级必须为此最后目的而奋斗。但是必须经过反帝反封建的民主革命的阶段，才能进到社会主义的阶段。所以，团结自己和团结人民，反对帝国主义和封建主义，为建立新民主主义的新中国而奋斗，这就是中国工人阶级的当前的任务。《中国工人》的出版，就是为了这一个任务。 《中国工人》将以通俗的言语解释许多道理给工人群众听，报道工人阶级抗日斗争的实际，总结其经验，为完成自己的任务而努力。……",
