    "answer": "抗日战争初期，中国共产党内和党外都有许多人轻视游击战争的重大战略作用，而只把自己的希望寄托于正规战争，特别是国民党军队的作战。毛泽东批驳了这种观点，同时写了这篇文章，指出抗日游击战争发展的正确道路。其结果，在抗日时期内，在一九三七年只有四万余人的八路军和新四军，到一九四五年日本投降时就发展成为一百多万人的大军，并创建了许多革命根据地，在抗日战争中起了伟大的作用，使蒋介石在抗日时期既不敢投降日本，又不敢发动全国规模的内战，而到一九四六年发动全国规模的内战时，由八路军新四军编成的人民解放军就有力量对付蒋介石的进攻了。 第一章 为什么提起游击战争的战略问题 抗日战争中，正规战争是主要的，游击战争是辅助的。这一点，我们已经正确地解决了。那末，游击战争就只有战术问题，为什么提起战略问题呢？ 如果我们是一个小国，游击战争只是在正规军的战役作战上起些近距离的直接的配合作用，那就当然只有战术问题，没有什么战略问题。又如果中国也像苏联那样的强大，敌人进来，很快就能赶出，或虽时间较久，但是被占地区不广，游击战争也只是一种战役的配合作用，当然也只有战术问题，没有什么战略问题。……",
