    "answer": "这是毛泽东为中共中央起草的对党内的指示。 一、某些地方的党组织违反党中央的工商业政策，造成严重破坏工商业的现象。对于这种错误，必须迅速加以纠正。这些地方的党委，在纠正这种错误的时候，必须从领导方针和领导方法两方面认真地进行检查。 二、在领导方针上。应当预先防止将农村中斗争地主富农、消灭封建势力的办法错误地应用于城市，将消灭地主富农的封建剥削和保护地主富农经营的工商业严格地加以区别，将发展生产、繁荣经济、公私兼顾、劳资两利的正确方针同片面的、狭隘的、实际上破坏工商业的、损害人民革命事业的所谓拥护工人福利的救济方针严格地加以区别。应当向工会同志和工人群众进行教育，使他们懂得，决不可只看到眼前的片面的福利而忘记了工人阶级的远大利益。应当引导工人和资本家在当地政府领导下，共同组织生产管理委员会，尽一切努力降低成本，增加生产，便利推销，达到公私兼顾、劳资两利、支援战争的目的。许多地方所犯的错误就是由于全部、大部或一部没有掌握上述方针而发生的。各中央局、分局应当明确提出此一问题，加以分析检查，定出正确方针，并分别发布党内指示和政府法令。……",
