    "answer": "这是毛泽东在中共中央党校开学典礼上的演说。 党校今天开学，我庆祝这个学校的成功。 今天我想讲一点关于我们的党的作风的问题。 为什么要有革命党？因为世界上有压迫人民的敌人存在，人民要推翻敌人的压迫，所以要有革命党。就资本主义和帝国主义时代说来，就需要一个如共产党这样的革命党。如果没有共产党这样的革命党，人民要想推翻敌人的压迫，简直是不可能的。我们是共产党，我们要领导人民打倒敌人，我们的队伍就要整齐，我们的步调就要一致，兵要精，武器要好。如果不具备这些条件，那末，敌人就不会被我们打倒。 现在我们的党还有什么问题呢？党的总路线是正确的，是没有问题的，党的工作也是有成绩的。党有几十万党员，他们在领导人民，向着敌人作艰苦卓绝的斗争。这是大家看见的，是不能怀疑的。",
