    "keywords": [
      "丢掉幻想",
      "准备斗争"
    ],
    "answer": "本文和下面的《别了，司徒雷登》、《为什么要讨论白皮书？》、《“友谊”，还是侵略？》、《唯心历史观的破产》四篇文章，都是毛泽东为新华社写的对于美国国务院白皮书和艾奇逊信件的评论。这些评论揭露了美国对华政策的帝国主义本质，批评了国内一部分资产阶级知识分子对于美国帝国主义的幻想，并且对中国革命的发生和胜利的原因作了理论上的说明。 美国国务院关于中美关系的白皮书以及艾奇逊国务卿给杜鲁门总统的信⑴，在现在这个时候发表，不是偶然的。这些文件的发表，反映了中国人民的胜利和帝国主义的失败，反映了整个帝国主义世界制度的衰落。帝国主义制度内部的矛盾重重，无法克服，使帝国主义者陷入了极大的苦闷中。 帝国主义给自己准备了灭亡的条件。殖民地半殖民地的人民大众和帝国主义自己国家内的人民大众的觉悟，就是这样的条件。帝国主义驱使全世界的人民大众走上消灭帝国主义的伟大斗争的历史时代。 帝国主义替这些人民大众准备了物质条件，也准备了精神条件。 工厂、铁道、枪炮等等，这些是物质条件。中国人民解放军的强大的物质装备，大部分是从美国帝国主义得来的，一部分是从日本帝国主义得来的，一部分是自己制造的。",
