    "answer": "*这是毛泽东同志在中国共产党第八次全国代表大会预备会议第一次会议上的讲话。 --------------------------------------------- 今天开第八次全国代表大会的预备会议。预备会议要开十几天，要作的主要事情，一是准备大会文件，二是进行中央委员会的预选，三是准备大会发言稿。 现在我讲几点意见。 第一点，关于大会的目的和宗旨。这次大会要解决什么问题，达到什么目的?总的说来，就是总结七大以来的经验，团结全党，团结国内外一切可以团结的力量，为建设伟大的社会主义中国而奋斗。",
