    "answer": "国民党反动派业已拒绝接受和平条件⑴，坚持其反民族反人民的罪恶的战争立场。全国人民希望人民解放军迅速消灭国民党反动派。我们已命令人民解放军奋勇前进，消灭一切敢于抵抗的国民党反动军队，逮捕一切怙恶不悛的战争罪犯，解放全国人民，保卫中国领土主权的独立和完整，实现全国人民所渴望的真正的统一。人民解放军所到之处，深望各界人民予以协助。兹特宣布约法八章，愿与我全体人民共同遵守之。 （一）保护全体人民的生命财产。各界人民，不分阶级、信仰和职业，均望保持秩序，采取和人民解放军合作的态度。人民解放军则采取和各界人民合作的态度。如有反革命分子或其他破坏分子，乘机捣乱、抢劫或破坏者，定予严办。 （二）保护民族工商农牧业。凡属私人经营的工厂、商店、银行、仓库、船舶、码头、农场、牧场等，一律保护，不受侵犯。希望各业员工照常生产，各行商店照常营业。……",
