    "answer": "这个布告是毛泽东为陕甘宁边区政府和八路军后方留守处起草的，目的是对付蒋介石集团的破坏活动。当时国共合作成立不久，蒋介石集团即阴谋破坏共产党领导的革命力量。破坏陕甘宁边区，是这种阴谋的一部分。毛泽东认为为了保护革命的利益，必须采取坚定的立场。这个布告打击了当时共产党内一部分同志在抗日统一战线中对于蒋介石集团的阴谋活动所采取的机会主义立场。……",
