    "answer": "*这是毛泽东同志为中共中央起草的党内指示。 省市级机关和高等学校大鸣大放的时间，大约十五天左右即足。反动分子猖狂进攻。党团员中的动摇分子或者叛变出去，或者动摇思叛。广大党团员中的积极分子及中间群众起而对抗。以大字报为战斗武器，双方在斗争中取得经验，锻炼人才。反动分子人数不过百分之几，最积极疯狂分子不过百分之一，故不足怕。不要为一时好似天昏地暗而被吓倒。反动分子将到本机关、本学校以外的工厂、学校去活动，要预作布置，实行挡驾。要召集工厂主要干部及老工人开会，说明有一些不好的资本家，不好的知识分子及社会上的反动分子正在向工人阶级及共产党猖狂进攻，要推倒工人阶级领导的政权，切记不要上他们的当。有人煽动，实行挡驾。街上贴反动标语，动员群众撕毁。工人要看清大局，不要闹事情。在此期间，不要提出福利工资等问题，一致对付反动派。……",
