    "answer": "*这是毛泽东同志为中共中央起草的党内指示。 ———————————————————— 反对官僚主义、反对命令主义、反对违法乱纪这件事，应当唤起我们各级领导机关的注意。 我党在“三反”中基本上解决了中央、大行政区、省市和专区四级许多工作人员中的贪污和浪费两个问题，也基本上解决了许多领导者和被领导的机关人员相脱离的这一部分官僚主义的问题；但对于不了解人民群众的痛苦，不了解离开自己工作机关稍为远一点的下情，不了解县、区、乡三级干部中存在着许多命令主义和违法乱纪的坏人坏事，或者虽然对于这些坏人坏事有一些了解，但是熟视无睹，不引起义愤，不感觉问题的严重，因而不采取积极办法去支持好人，惩治坏人，发扬好事，消灭坏事，这样一方面的官僚主义，则在许多地区、许多方面和许多部门，还是基本上没有解决。即如处理人民来信一事，据报有的省人民政府就积压了七万多件没有处理，省以下各级党政组织积压了多少人民来信，则我们还不知道，可以想象是不少的。这些人民来信大都是有问题要求我们给他们解决的，其中许多是控告干部无法无天的罪行而应当迅速处理的。……",
