    "answer": "这是毛泽东为延安《解放日报》写的社论。 我们在敌后解放区中那些比较巩固的根据地内，能够和必须发动军民的生产运动的问题，早已解决了，不成问题了。但是在游击区中，在敌后之敌后，是否也能够这样，在过去，在许多人的思想中，还是没有解决的，这是因为还缺少证明的缘故。 可是现在有了证据了。根据一月二十八日《解放日报》所载张平凯同志关于晋察冀游击队的生产运动的报道，晋察冀边区的许多游击区内，已于一九四四年进行了大规模的生产，并且收到了极好的成绩。张同志报道中所提到的区域和部队，有冀中的第六分区，第二分区的第四区队，第四分区的第八区队，徐定支队，保满支队，云彪支队，有山西的代县和崞县⑴的部队。那些区域的环境是很恶劣的：“敌伪据点碉堡林立，沟墙公路如网，敌人利用它的军事上的优势和便利的交通条件，时常对我袭击，包围，‘清剿’；游击队为了应付环境，往往一日数处地转移。”然而他们仍然能够于战争的间隙，进行了生产。其结果：“使得大家的给养有了改善，每人每日增加到五钱油和盐，一斤菜，每月斤半肉。而且几年没有用过的牙刷、牙粉和识字本，现在也都齐全了。”大家看，谁说游击区不能生产呢！……",
