    "answer": "这是毛泽东为中共中央起草的电报。因为它的内容不但适用于洛阳，也基本上适用于一切新解放的城市，所以这个电报同时发给了其他前线和其他地区的领导同志。 此次再克洛阳⑴，可能巩固。关于城市政策，应注意下列各点。 一、极谨慎地清理国民党统治机构，只逮捕其中主要反动分子，不要牵连太广。 二、对于官僚资本要有明确界限，不要将国民党人经营的工商业都叫作官僚资本而加以没收。对于那些查明确实是由国民党中央政府、省政府、县市政府经营的，即完全官办的工商业，应该确定归民主政府接管营业的原则。但如民主政府一时来不及接管或一时尚无能力接管，则应该暂时委托原管理人负责管理，照常开业，直至民主政府派人接管时为止。对于这些工商业，应该组织工人和技师参加管理，并且信任他们的管理能力。如国民党人已逃跑，企业处于停歇状态，则应该由工人和技师选出代表，组织管理委员会管理，然后由民主政府委任经理和厂长，同工人一起加以管理。对于著名的国民党大官僚所经营的企业，应该按照上述原则和办法处理。 对于小官僚和地主所办的工商业，则不在没收之列。一切民族资产阶级经营的企业，严禁侵犯。",
