    "q": "南京政府向何处去？",
    "keywords": [
      "南京政府向何处去？"
    ],
    "answer": "两条路摆在南京国民党政府及其军政人员的面前：一条是向蒋介石战犯集团及其主人美国帝国主义靠拢，这就是继续与人民为敌，而在人民解放战争中和蒋介石战犯集团同归于尽；一条是向人民靠拢，这就是与蒋介石战犯集团和美国帝国主义决裂，而在人民解放战争中立功赎罪，以求得人民的宽恕和谅解。第三条路是没有的。 在南京的李宗仁何应钦政府⑴中，存在着三部分人。一部分人坚持地走第一条路。无论他们在口头上怎样说得好听，在行动上他们是继续备战，继续卖国，继续压迫和屠杀要求真和平的人民。他们是蒋介石的死党。一部分人愿意走第二条路，但是他们还不能作出有决定性的行动。第三部分是一些徘徊歧路、动向不明的人们。他们既不想得罪蒋介石和美国政府，又想得到人民民主阵营的谅解和容纳。但这是幻想，是不可能的。 南京的李宗仁何应钦政府，基本上是第一部分人和第三部分人的混合物，第二部分人为数甚少。这个政府到今天为止，仍然是蒋介石和美国政府的工具。……",
