    "answer": "这是毛泽东为中共中央起草的决定。 （一）帝国主义世界大战的爆发，是由于各帝国主义国家企图解脱新的经济危机和政治危机。战争的性质，无论在德国或英法方面，都是非正义的掠夺的帝国主义战争。全世界共产党都应该坚决反对这种战争，反对社会民主党拥护这种战争叛卖无产阶级的罪恶行为。社会主义的苏联依然坚持其和平政策，对战争的双方严守中立，用出兵波兰的行动制止德国侵略势力向东扩展，巩固东欧和平，解放被波兰统治者所压迫的西部乌克兰和白俄罗斯的兄弟民族。苏联和其周围各国订立了各种条约，以预防国际反动势力的可能的袭击，并为世界和平的恢复而奋斗。 （二）日本帝国主义在国际新形势下的政策是专力进攻中国，企图解决中国问题，以准备将来扩大其对国际的冒险行动。其企图用以解决中国问题的方针是： 一、对于占领区域，是加以确保，作为灭亡全中国的准备。为达此目的，它需要“扫荡”抗日游击根据地，需要进行经济开发和建立伪政权，需要消灭中国人的民族精神。 二、对于我后方，是以政治进攻为主，而以军事进攻为辅。所谓政治进攻，就是着重于分化抗日统一战线，分裂国共合作，引诱国民党政府投降，而不是着重于大规模的军事进攻。",
