    "answer": "这是毛泽东在第二次世界大战结束不久，关于国际形势和国内形势的一篇很重要的谈话。在这篇谈话里，毛泽东提出了“一切反动派都是纸老虎”的著名论点。这个论点，武装了中国人民的思想，加强了中国人民的胜利信心，在人民解放战争中，起了极其伟大的作用。同列宁把帝国主义看做“泥足巨人”一样，毛泽东把帝国主义和一切反动派看做纸老虎，都是从它们的本质说的。这是革命人民的一个根本战略思想。从第二次国内革命战争时期以来，毛泽东曾经多次地指出，革命者必须在战略上，在全体上，藐视敌人，敢于同他们斗争，敢于夺取胜利；同时，又要在战术上，在策略上，在每一个局部上，在每一个具体斗争问题上，重视敌人，采取谨慎态度，讲究斗争艺术，根据不同的时间、地点和条件，采取适当的斗争形式，以便一步一步地孤立敌人和消灭敌人。毛泽东一九五八年十二月一日在中共八届六中全会期间写的《关于帝国主义和一切反动派是不是真老虎的问题》一文中指出：“同世界上一切事物无不具有两重性（即对立统一规律）一样，帝国主义和一切反动派也有两重性，它们是真老虎又是纸老虎。历史上奴隶主阶级、封建地主阶级和资产阶级，在它们取得统治权力以前和取得统治权力以后的一段时间内，它……",
