    "answer": "自从一月一日蒋匪介石发动和平攻势以后，曾经连篇累牍地表示自己是愿意“缩短战争时间”，“减轻人民痛苦”，“以拯救人民为前提”的国民党反动派的英雄好汉们，一到二月上旬，和平的调子就突然低落下去，“和共党周旋到底”的老调忽又高弹起来。最近数日，更是如此。二月十三日，国民党中央宣传部发给“各党部各党报”的《特别宣传指示》上说：“叶剑英向我后方宣传中共对和平有诚意，而指责政府军事布置为无诚意谋和。各报对此，必须依据下列各点从正面与侧面力加驳斥。”这个《特别宣传指示》一连列举了好几点应当“驳斥”的理由。“政府与其无条件投降，不如作战到底。”“毛泽东一月十四日声明所提八点为亡国条件，政府原不应接受。”“中共应负破坏和平之责任。今日中共反而提出所谓战犯名单，将政府负责人士尽皆列入，更要求政府先行逮捕，其蛮横无理，显而易见。中共如不改变此种作风，则和平商谈之途径，势难寻觅。”两星期以前那种如丧考妣地急着要谈判的神气，再也不见了。所谓“缩短战争时间”，“减轻人民痛苦”，“以拯救人民为前提”这些传遍人间、沁人心脾的名句，再也不提了。假如中共不愿意改变自己的“作风”，一定要惩办战争罪犯，那就不能谈和平了。究竟……",
