    "answer": "“政府自抗战结束以后，即以和平建国方针力谋中共问题之和平解决。经过一年半之时间，一切协议皆为中共所破坏，故中共应负破坏和平之责任。今日中共反而提出所谓战犯名单，将政府负责人士尽皆列入，更要求政府先行逮捕，其蛮横无理，显而易见。中共如不改变此种作风，则和平商谈之途径，势难寻觅。”以上是一九四九年二月十三日国民党中央宣传部所发《特别宣传指示》中关于战争责任问题的全部论点。 这个论点，不是别人的，是第一名战争罪犯蒋介石的。蒋介石在其元旦声明里说：“中正为三民主义的信徒，秉承国父的遗教，本不愿在对日作战之后再继之以剿匪的军事，来加重人民的痛苦。所以抗日战事甫告结束，我们政府立即揭举和平建国的方针，更进而以政治商谈、军事调处的方法解决共党问题。不意经过了一年有半的时间，共党对于一切协议和方案都横加梗阻，使其不能依预期的步骤见诸实施。而最后更发动其全面武装叛乱，危害国家的生存。我政府迫不得已，乃忍痛动员，从事戡乱。”……",
