    "q": "三个月总结",
    "keywords": [
      "三个月总结"
    ],
    "answer": "这是毛泽东为中共中央起草的对党内的指示。这个指示，详细地总结了一九四六年七月全国规模内战爆发以来的三个月战争的一系列经验，提出了人民解放军在今后的作战方针和作战任务，指出了人民解放战争在克服一个时期的困难以后必然能够取得胜利。对于支持和配合人民解放战争所需要解决的解放区内部的土地改革问题，发展解放区的生产问题，加强国民党统治区的群众斗争的领导问题，以及其他有关问题，这个文件也作了原则的说明。 （一）七月二十日中央对时局的指示⑴上说：“我们是能够战胜蒋介石的。全党对此应当有充分的信心。”七、八、九三个月的作战，业已证明此项断语是正确的。 （二）除了政治上经济上的基本矛盾，蒋介石无法克服，为我必胜蒋必败的基本原因之外，在军事上，蒋军战线太广与其兵力不足之间，业已发生了尖锐的矛盾。此种矛盾，必然要成为我胜蒋败的直接原因。 （三）向解放区进攻的全部正规蒋军，除伪军、保安队、交通警察部队等不计外，共计一百九十几个旅。此数以外，至多再从南方抽调一部分兵力向北增援，此后即难再调。而此一百九十几个旅中，过去三个月内，已被我军歼灭二十五个旅。今年二月至六月被我军在东北所歼灭者，尚未计算在内。……",
    "source": "《毛泽东选集》",
