    "answer": "这个命令是毛泽东起草的。在国民党反动政府拒绝签订国内和平协定以后，人民解放军遵照毛泽东主席和朱德总司令的这个命令，向尚未解放的广大地区，举行了规模空前的全面大进军。刘伯承、邓小平等领导的第二野战军和陈毅、粟裕、谭震林等领导的第三野战军，于一九四九年四月二十日夜起，至二十一日，在西起九江东北的湖口，东至江阴，长达五百余公里的战线上，强渡长江，彻底摧毁国民党军苦心经营了三个半月的长江防线。四月二十三日，解放了国民党二十二年来的反革命统治中心南京，宣告了国民党反动统治的覆灭。接着，又分路向南挺进，于五月三日解放杭州，五月二十二日解放南昌，五月二十七日攻占中国最大的城市上海。七月，开始进军福建。八月十七日解放福州，十月十七日解放厦门。林彪、罗荣桓等领导的第四野战军，于五月十四日，在武汉以东团风至武穴间一百余公里的地段上，强渡长江。五月十六、十七两日，解放华中的重镇武昌、汉阳和汉口。接着，又南下湖南。国民党湖南省主席程潜、第一兵团司令陈明仁，于八月四日宣布起义，湖南省和平解放。第四野战军在九、十月间进行衡（阳）宝（庆）战役，歼灭了国民党白崇禧军的主力以后，又向广东、广西进军。十月十四日解放广州，……",
