    "answer": "这是毛泽东在陕甘宁边区劳动英雄和模范工作者大会上的讲话。 各位劳动英雄，各位模范工作者！ 你们开了会，总结了经验，大家欢迎你们，尊敬你们。你们有三种长处，起了三个作用。第一个，带头作用。这就是因为你们特别努力，有许多创造，你们的工作成了一般人的模范，提高了工作标准，引起了大家向你们学习。第二个，骨干作用。你们的大多数现在还不是干部，但是你们已经是群众中的骨干，群众中的核心，有了你们，工作就好推动了。到了将来，你们可能成为干部，你们现在是干部的后备军。第三个，桥梁作用。你们是上面的领导人员和下面的广大群众之间的桥梁，群众的意见经过你们传上来，上面的意见经过你们传下去。 你们有许多的长处，有很大的功劳，但是你们切记不可以骄傲。你们被大家尊敬，是应当的，但是也容易因此引起骄傲。如果你们骄傲起来，不虚心，不再努力，不尊重人家，不尊重干部，不尊重群众，你们就会当不成英雄和模范了。过去已有一些这样的人，希望你们不要学他们。 你们的经验，这次会议做了总结。这个总结文件说得很好，不但这里适用，各地也可以适用，我就不讲这些了。我想讲一点我们的经济工作。",
