    "answer": "我们的政策，不光要使领导者知道，干部知道，还要使广大的群众知道。有关政策的问题，一般地都应当在党的报纸上或者刊物上进行宣传。我们正在进行土地制度的改革。有关土地改革的各项政策，都应当在报上发表，在电台广播，使广大群众都能知道。群众知道了真理，有了共同的目的，就会齐心来做。这和打仗一样，要打好仗，不光要干部齐心，还要战士齐心。陕北的部队经过整训诉苦以后，战士们的觉悟提高了，明了了为什么打仗，怎样打法，个个磨拳擦掌，士气很高，一出马就打了胜仗。群众齐心了，一切事情就好办了。马克思列宁主义的基本原则，就是要使群众认识自己的利益，并且团结起来，为自己的利益而奋斗。报纸的作用和力量，就在它能使党的纲领路线，方针政策，工作任务和工作方法，最迅速最广泛地同群众见面。……",
