    "answer": "这是毛泽东为新华社写的评论。 国民党中央宣传部发言人发表谈话说，第十八集团军朱德总司令于八月十日在延安总部所发表的限令敌伪投降的命令⑴，是一种“唐突和非法之行动”。这种评论，荒谬绝伦。根据这种意见，可以逻辑地解释为朱德总司令根据波茨坦公告⑵和敌人投降的意向，下令给所属部队促使敌伪投降，倒反错了，应该劝使敌伪拒绝投降，才是对的，才算合法。无怪中国法西斯头子独夫民贼蒋介石，在敌人尚未真正接受投降之前，敢于“命令”解放区抗日军队“应就原地驻防待命”，束手让敌人来打。无怪这同一个法西斯头子，又敢于“命令”所谓地下军（实际上就是实行“曲线救国”⑶的伪军和与敌伪合流的戴笠系特务⑷）和伪军，“负责维持地方治安”，而不许解放区抗日军队向敌伪“擅自行动”。这样的敌我倒置，真是由蒋介石自己招供，活画出他一贯勾结敌伪、消除异己的全部心理了。可是中国解放区的人民抗日军队，绝不会中此毒计。他们知道：朱德总司令的命令，正是坚决地执行波茨坦公告第二项的规定：“对日作战，直至其停止抵抗为止。”而蒋介石的所谓“命令”，正是违反了他自己签字的波茨坦公告。只要拿这一比，就知道谁是不“恪守盟邦共同协议之规定”了。……",
